 // Only the existing support.load successful-result identity can mint this
 // claim. Reuse its parsed/frozen profile and the one existing inert DOM.
 const pins=certifies(value);if(!pins)return false;
 const p=value.profile,c=p?.authoredCodec;
 const compatible=!!c&&c.schema===schema&&c.sourceSha256===approved.sourceSha256&&c.firstIifeSha256===approved.firstIifeSha256&&c.derivedHTMLSha256===pins.htmlSha256&&p.bindings?.derivedHTMLSha256===pins.htmlSha256;
 const qualified=compatible&&c.eligible===true&&JSON.stringify(c.cohort)===JSON.stringify(approved.cohort)&&JSON.stringify(cohort)===JSON.stringify(approved.cohort)&&JSON.stringify(c.config)===approved.configJSON&&environment();
 if(!qualified)return false;
 const r={qualified,bad:false,accepted:0,valid,doc:null,root:null,head:null,body:null,observer:null,configJSON:approved.configJSON,executionScripts:new WeakSet(),topHead:[...parsed.head.childNodes],topBody:[...parsed.body.childNodes],htmlAttrs:attrs(parsed.documentElement),bodyAttrs:attrs(parsed.body),parsed};
 records.set(parsed,r);return true;
}
